8. "params" Keyword <pre><code>// params: nhận số lượng arguments không xác định
static int Sum(params int[] numbers)
{
    int total = 0;
    foreach (int n in numbers)
        total += n;
    return total;
}

int result = Sum(1, 2, 3);           // 6
int result2 = Sum(1, 2, 3, 4, 5);   // 15
